#ifndef ESCROW_POLICY_H
#define ESCROW_POLICY_H

#include <stddef.h>

// A role policy, generated by Nix (flake.nix: mkRole) and only read here:
//
//   env /nix/store/<hash>-escrow-env-<name>
//   store /nix/store/<hash>-<name>
//   ...
//
// env is the role's buildEnv: the agent's PATH is env/bin. The store lines
// are its full runtime closure (closureInfo), the only store paths the jail
// can see. env must be one of them. No blank or comment lines.
struct policy {
  const char *env; // points into store
  char **store;
  size_t nstore;
};

// Host side, before the jail exists. Reads and validates `file`: exactly
// one env line, every store path a well-formed /nix/store/<32 nix-base32
// chars>-<name> that exists as a dir or regular file, no store path twice.
// The strings live until exit (never freed). Exits with status 1 on any
// malformed line or syscall failure.
void policy_load(struct policy *p, const char *file);

#endif
